<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface Choice { id: string; name: string }
interface VariantChoice { id: string; sku: string; name: string | null; product: string }
interface PriceListChoice { id: string; name: string; currency: string }
interface Promotion { id: string; name: string; internal_code: string | null; description: string | null; status: string; discount_type: string; discount_value: string; currency: string | null; starts_at: string | null; ends_at: string | null; priority: number; scope: string; is_currently_eligible: boolean }
interface Preview { base_amount: string; final_amount: string; total_discount: string; applied_promotions: { id: string; name: string; internal_code: string | null }[] }

const props = defineProps<{ promotion: Promotion; selected: { product_ids: string[]; category_ids: string[]; variant_ids: string[] }; statuses: string[]; discountTypes: string[]; scopes: string[]; currencies: string[]; products: Choice[]; categories: Choice[]; variants: VariantChoice[]; priceLists: PriceListChoice[]; targetSearch: string; preview: Preview | null; previewSelection: { variant_id: string; price_list_id: string } }>();
const page = usePage<PageProps>();
const canUpdate = computed(() => page.props.currentTenantMembership?.permissions.includes('promotions.update') ?? false);
const canEdit = computed(() => canUpdate.value && props.promotion.status !== 'ARCHIVED');
const form = useForm({ name: props.promotion.name, internal_code: props.promotion.internal_code ?? '', description: props.promotion.description ?? '', status: props.promotion.status, discount_type: props.promotion.discount_type, discount_value: props.promotion.discount_value, currency: props.promotion.currency ?? '', starts_at: props.promotion.starts_at ?? '', ends_at: props.promotion.ends_at ?? '', priority: props.promotion.priority, scope: props.promotion.scope, product_ids: [...props.selected.product_ids], category_ids: [...props.selected.category_ids], variant_ids: [...props.selected.variant_ids] });
const previewVariant = ref(props.previewSelection.variant_id);
const previewPriceList = ref(props.previewSelection.price_list_id);
const targetSearch = ref(props.targetSearch);
const update = () => form.put(`/admin/promotions/${props.promotion.id}`);
const loadPreview = () => router.get(`/admin/promotions/${props.promotion.id}/edit`, { preview_variant: previewVariant.value, preview_price_list: previewPriceList.value }, { preserveState: false, replace: true });
const searchTargets = () => router.get(`/admin/promotions/${props.promotion.id}/edit`, { target_search: targetSearch.value }, { preserveState: false, replace: true });
</script>

<template>
    <Head :title="promotion.name" /><AdminLayout><section><div class="flex flex-wrap items-end justify-between gap-5"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ promotion.internal_code ?? 'Promotion' }} / {{ promotion.status }}</p><h1 class="mt-4 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">{{ promotion.name }}</h1><p class="mt-3 text-sm" :class="promotion.is_currently_eligible ? 'text-emerald-800' : 'text-[#637067]'">{{ promotion.is_currently_eligible ? 'Currently eligible' : 'Not currently eligible' }}. Times use UTC and end is exclusive.</p></div><Link href="/admin/promotions" class="font-semibold text-emerald-800">Back to promotions</Link></div>
    <form class="mt-8 flex max-w-xl gap-3" @submit.prevent="searchTargets"><input v-model="targetSearch" type="search" placeholder="Find target product, category, or SKU" class="min-w-0 flex-1 border bg-white px-4 py-3" /><button class="border border-[#17211b] px-5 py-3 font-semibold">Find targets</button></form>
    <form class="mt-6 grid gap-8 border border-[#17211b]/15 bg-[#f8f5ed] p-6 sm:p-8" @submit.prevent="update">
        <div class="grid gap-5 sm:grid-cols-2"><div><label class="mb-2 block text-sm font-semibold">Name</label><input v-model="form.name" :disabled="!canEdit" required maxlength="160" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100" /><FieldError :message="form.errors.name" /></div><div><label class="mb-2 block text-sm font-semibold">Internal code</label><input v-model="form.internal_code" :disabled="!canEdit" maxlength="60" class="w-full border bg-white px-4 py-3 font-mono uppercase disabled:bg-stone-100" /><FieldError :message="form.errors.internal_code" /></div></div>
        <div><label class="mb-2 block text-sm font-semibold">Description</label><textarea v-model="form.description" :disabled="!canEdit" rows="3" maxlength="10000" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100" /><FieldError :message="form.errors.description" /></div>
        <div class="grid gap-5 sm:grid-cols-4"><div><label class="mb-2 block text-sm font-semibold">Status</label><select v-model="form.status" :disabled="!canEdit" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100"><option v-for="status in statuses" :key="status">{{ status }}</option></select><FieldError :message="form.errors.status" /></div><div><label class="mb-2 block text-sm font-semibold">Discount type</label><select v-model="form.discount_type" :disabled="!canEdit" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100"><option v-for="type in discountTypes" :key="type">{{ type }}</option></select><FieldError :message="form.errors.discount_type" /></div><div><label class="mb-2 block text-sm font-semibold">Value</label><input v-model="form.discount_value" :disabled="!canEdit" required inputmode="decimal" class="w-full border bg-white px-4 py-3 font-mono disabled:bg-stone-100" /><FieldError :message="form.errors.discount_value" /></div><div><label class="mb-2 block text-sm font-semibold">Currency</label><select v-model="form.currency" :disabled="!canEdit || form.discount_type !== 'FIXED_AMOUNT'" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100"><option value="">Choose</option><option v-for="currency in currencies" :key="currency">{{ currency }}</option></select><FieldError :message="form.errors.currency" /></div></div>
        <div class="grid gap-5 sm:grid-cols-3"><div><label class="mb-2 block text-sm font-semibold">Starts at (UTC)</label><input v-model="form.starts_at" :disabled="!canEdit" type="datetime-local" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100" /><FieldError :message="form.errors.starts_at" /></div><div><label class="mb-2 block text-sm font-semibold">Ends at (UTC, exclusive)</label><input v-model="form.ends_at" :disabled="!canEdit" type="datetime-local" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100" /><FieldError :message="form.errors.ends_at" /></div><div><label class="mb-2 block text-sm font-semibold">Priority</label><input v-model.number="form.priority" :disabled="!canEdit" type="number" min="-1000000" max="1000000" class="w-full border bg-white px-4 py-3 font-mono disabled:bg-stone-100" /><FieldError :message="form.errors.priority" /></div></div>
        <fieldset :disabled="!canEdit"><legend class="text-lg font-semibold">Catalog scope</legend><div class="mt-3 flex gap-5"><label v-for="scope in scopes" :key="scope" class="flex items-center gap-2"><input v-model="form.scope" type="radio" :value="scope" />{{ scope === 'ALL' ? 'All catalog' : 'Selected targets' }}</label></div><FieldError :message="form.errors.scope" /></fieldset>
        <div v-if="form.scope === 'SELECTED'" class="grid gap-6 lg:grid-cols-3"><fieldset :disabled="!canEdit"><legend class="mb-3 font-semibold">Products</legend><div class="grid max-h-72 gap-2 overflow-y-auto"><label v-for="product in products" :key="product.id" class="flex items-center gap-3 border bg-white p-3"><input v-model="form.product_ids" type="checkbox" :value="product.id" />{{ product.name }}</label></div><FieldError :message="form.errors.product_ids" /></fieldset><fieldset :disabled="!canEdit"><legend class="mb-3 font-semibold">Exact categories</legend><div class="grid max-h-72 gap-2 overflow-y-auto"><label v-for="category in categories" :key="category.id" class="flex items-center gap-3 border bg-white p-3"><input v-model="form.category_ids" type="checkbox" :value="category.id" />{{ category.name }}</label></div><FieldError :message="form.errors.category_ids" /></fieldset><fieldset :disabled="!canEdit"><legend class="mb-3 font-semibold">Variants</legend><div class="grid max-h-72 gap-2 overflow-y-auto"><label v-for="variant in variants" :key="variant.id" class="flex items-center gap-3 border bg-white p-3"><input v-model="form.variant_ids" type="checkbox" :value="variant.id" /><span>{{ variant.product }}<small class="block font-mono">{{ variant.sku }} / {{ variant.name }}</small></span></label></div><FieldError :message="form.errors.variant_ids" /></fieldset></div>
        <button v-if="canEdit" :disabled="form.processing" class="w-fit bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-60">{{ form.processing ? 'Saving...' : 'Save promotion' }}</button>
    </form>
    <section class="mt-10 border border-[#17211b]/15 bg-white p-6 sm:p-8"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Server-side preview</p><h2 class="mt-3 text-3xl font-semibold">Current effective price</h2><p class="mt-2 text-sm text-[#637067]">Uses the saved configuration and all currently eligible promotions. The backend remains authoritative.</p><form class="mt-5 flex flex-wrap gap-3" @submit.prevent="loadPreview"><select v-model="previewVariant" required class="min-w-64 border bg-white px-4 py-3"><option value="">Choose variant</option><option v-for="variant in variants" :key="variant.id" :value="variant.id">{{ variant.product }} / {{ variant.sku }}</option></select><select v-model="previewPriceList" required class="border bg-white px-4 py-3"><option value="">Choose price list</option><option v-for="list in priceLists" :key="list.id" :value="list.id">{{ list.name }} / {{ list.currency }}</option></select><button class="border border-[#17211b] px-5 py-3 font-semibold">Calculate</button></form><div v-if="preview" class="mt-6 grid gap-4 border-l-4 border-emerald-700 bg-[#f8f5ed] p-5 sm:grid-cols-4"><div><small class="uppercase text-[#637067]">Base</small><p class="mt-1 font-mono text-xl">{{ preview.base_amount }}</p></div><div><small class="uppercase text-[#637067]">Discount</small><p class="mt-1 font-mono text-xl">{{ preview.total_discount }}</p></div><div><small class="uppercase text-[#637067]">Final</small><p class="mt-1 font-mono text-xl">{{ preview.final_amount }}</p></div><div><small class="uppercase text-[#637067]">Applied</small><p class="mt-1 font-semibold">{{ preview.applied_promotions.map((item) => item.name).join(', ') || 'None' }}</p></div></div><p v-else-if="previewSelection.variant_id" class="mt-5 text-sm text-[#637067]">The selected variant has no base price in that list.</p></section>
    </section></AdminLayout>
</template>
